import{_ as s,C as a,o as l,c as i,a5 as c,E as o,j as t,a as e}from"./chunks/framework.DuVjalqf.js";const h="/rb_cobot_docs_muscat/images/settings/after-action-overview.avif",g="/rb_cobot_docs_muscat/images/settings/after-action-setting-box.avif",p="/rb_cobot_docs_muscat/images/settings/after-action-changed.avif",S=JSON.parse('{"title":"After Action","description":"","frontmatter":{"title":"After Action","outline":[2,3]},"headers":[],"relativePath":"manual/settings/after-action.md","filePath":"manual/settings/after-action.md","lastUpdated":1792396350000}'),f={name:"manual/settings/after-action.md"};function b(u,r,m,A,y,x){const d=a("DemoFrame"),n=a("ScenarioSteps");return l(),i("div",null,[r[0]||(r[0]=c('<h1 id="after-action" tabindex="-1">After Action <a class="header-anchor" href="#after-action" aria-label="Permalink to &quot;After Action&quot;">​</a></h1><p><strong>After Action</strong>은 로봇에서 특정 일이 끝난 뒤에 <strong>사용자 스크립트를 자동으로 실행</strong>하도록 정하는 설정입니다. 시점마다 &quot;아무것도 하지 않음&quot; 또는 &quot;사용자 스크립트 0~15 중 하나 실행&quot;을 고를 수 있습니다.</p><p>이 문서에서는 <strong>설정 &gt; 일반 &gt; After Action</strong> 화면에서 다음을 해 봅니다.</p><ul><li>16가지 시점과 현재 설정 한눈에 보기</li><li>시점을 골라 실행할 스크립트 정하기</li><li>저장하고 카드에서 결과 확인하기</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><p>왼쪽 설정 메뉴의 <strong>일반 &gt; After Action</strong>을 누르면 나타나는 화면입니다. 아직 아무것도 바꾸지 않은 상태이며 첫 번째 시점(After System Boot)이 선택되어 있습니다.</p><p><img src="'+h+'" alt="After Action 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>영역</th><th>역할</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td>시점 탭</td><td>시점 이름이 가로로 나열됩니다. 누르면 해당 카드가 선택됩니다. 기본값이 아닌 동작이 지정된 시점은 <span class="hl-yellow">노란색</span>으로 표시됩니다.</td></tr><tr><td style="text-align:center;">②</td><td>카드 목록</td><td>시점마다 카드가 하나씩 있고, <strong>동작 종류</strong>에 현재 설정된 동작이 표시됩니다. 카드를 눌러 선택할 수도 있습니다. 기본값이 아닌 동작은 <span class="hl-yellow">노란색</span>으로 표시됩니다.</td></tr><tr><td style="text-align:center;">③</td><td>설정 영역</td><td>선택한 시점의 이름과 동작을 바꾸는 영역입니다. 아래에서 자세히 설명합니다.</td></tr></tbody></table></div><h3 id="설정-영역-3-의-구성" tabindex="-1">설정 영역(③)의 구성 <a class="header-anchor" href="#설정-영역-3-의-구성" aria-label="Permalink to &quot;설정 영역(③)의 구성&quot;">​</a></h3><p>설정 영역을 확대한 화면입니다. 아래는 <strong>After Servo On</strong>의 동작을 Run User Script 0으로 골랐지만 아직 저장하지 않은 상태입니다.</p><p><img src="'+g+'" alt="설정 영역의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">④</td><td><strong>After Action</strong> 선택 상자</td><td><strong>Do nothing</strong>(아무것도 하지 않음) 또는 <strong>Run User Script 0~15</strong> 중에서 고릅니다. 목록의 첫 항목(Do nothing)이 아닌 값을 고르면 선택 상자의 글자가 <span class="hl-yellow">노란색</span>으로 바뀝니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>초기화</strong></td><td>고르기만 하고 <strong>저장하지 않은 값</strong>을 저장된 값으로 되돌립니다. 고른 값이 저장된 값과 같으면 눌리지 않습니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>저장</strong></td><td>선택한 동작을 해당 시점에 저장합니다. <strong>저장해야 설정이 적용됩니다.</strong></td></tr></tbody></table></div><h2 id="기본값이-아닌-값-표시" tabindex="-1">기본값이 아닌 값 표시 <a class="header-anchor" href="#기본값이-아닌-값-표시" aria-label="Permalink to &quot;기본값이 아닌 값 표시&quot;">​</a></h2><p>설정 화면에는 <strong>기본값이 아닌 값을 <span class="hl-yellow">노란색</span>으로 표시</strong>해 한눈에 구별하게 하는 기능이 있습니다. (밝은 테마에서는 주황색으로 보입니다.) After Action에서는 아래 세 곳에 적용됩니다. 기본값은 <strong>Do nothing</strong>입니다.</p><p><img src="'+p+'" alt="기본값이 아닌 값 표시"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>위치</th><th>표시</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td>시점 탭</td><td>기본값이 아닌 동작이 저장된 시점의 이름이 <span class="hl-yellow">노란색</span>이 됩니다.</td></tr><tr><td style="text-align:center;">②</td><td>카드의 <strong>동작 종류</strong></td><td>저장된 동작이 Do nothing이 아니면 <span class="hl-yellow">노란색</span>이 되고, 카드 글자도 굵게 표시됩니다.</td></tr><tr><td style="text-align:center;">③</td><td>선택 상자</td><td>고른 값이 Do nothing이 아니면 <span class="hl-yellow">노란색</span>입니다. <strong>저장 전에도</strong> 바뀝니다.</td></tr></tbody></table></div><p>다른 설정 화면에서는 다음 경우에 <span class="hl-yellow">노란색</span>으로 표시됩니다.</p><table tabindex="0"><thead><tr><th>화면</th><th>노란색으로 표시되는 경우</th></tr></thead><tbody><tr><td>After Action</td><td>동작이 <strong>Do nothing</strong>이 아닐 때 (시점 탭·카드·선택 상자)</td></tr><tr><td>사용자 스크립트</td><td>카드의 스크립트가 <strong>비어 있을 때</strong>(<code>no set script</code>, 다른 화면과 반대). 스크립트가 있는 항목의 탭은 <span class="hl-yellow">노란색</span>으로 표시됩니다.</td></tr><tr><td>디지털 입력·출력 기능</td><td>카드의 기능이 지정되어 있을 때</td></tr><tr><td>디지털 입력 필터</td><td>지연 값이 <strong>1이 아닐 때</strong> (카드·탭)</td></tr></tbody></table><h2 id="시점과-동작" tabindex="-1">시점과 동작 <a class="header-anchor" href="#시점과-동작" aria-label="Permalink to &quot;시점과 동작&quot;">​</a></h2><h3 id="시점" tabindex="-1">시점 <a class="header-anchor" href="#시점" aria-label="Permalink to &quot;시점&quot;">​</a></h3><p>시점은 &quot;무슨 일이 끝난 뒤에 실행할 것인가&quot;를 정합니다. 시점마다 따로 동작을 지정합니다.</p><div class="tbl-nowrap-1"><table tabindex="0"><thead><tr><th>시점</th><th>실행되는 때</th></tr></thead><tbody><tr><td>After System Boot</td><td>제어 시스템이 시작된 뒤</td></tr><tr><td>After Servo On</td><td>서보 켜기에 성공한 뒤</td></tr><tr><td>After Real Mode On</td><td>서보 켜기에 성공한 뒤 Real Mode(실제 로봇 모드)가 켜져 있을 때</td></tr><tr><td>After Simul Mode On</td><td>Simul Mode(시뮬레이션 모드)를 켠 뒤</td></tr><tr><td>After Arm DC Power On</td><td>로봇 팔의 DC 전원을 켠 뒤</td></tr><tr><td>After Arm DC Power Off</td><td>로봇 팔의 DC 전원을 끈 뒤</td></tr><tr><td>After Program Start</td><td>프로그램을 시작할 때</td></tr><tr><td>After Program Stop</td><td>프로그램이 끝날 때</td></tr><tr><td>After Direct Teaching On</td><td>직접 교시를 켠 뒤</td></tr><tr><td>After Direct Teaching Off</td><td>직접 교시를 끈 뒤</td></tr><tr><td>After Collision Occur</td><td>충돌이 발생한 뒤</td></tr><tr><td>After Collision Reset</td><td>충돌 상태를 해제(리셋)한 뒤</td></tr><tr><td>After Pause</td><td>일시 정지한 뒤</td></tr><tr><td>After Resume</td><td>일시 정지한 것을 다시 시작한 뒤</td></tr><tr><td>After Move Start</td><td>이동을 시작한 뒤</td></tr><tr><td>After Move Done</td><td>이동을 마친 뒤</td></tr></tbody></table></div><h3 id="동작" tabindex="-1">동작 <a class="header-anchor" href="#동작" aria-label="Permalink to &quot;동작&quot;">​</a></h3><table tabindex="0"><thead><tr><th>선택</th><th>의미</th></tr></thead><tbody><tr><td><strong>Do nothing</strong></td><td>아무것도 하지 않습니다. 기본값입니다.</td></tr><tr><td><strong>Run User Script N</strong> (N = 0~15)</td><td><strong>사용자 스크립트</strong> 설정에서 N번에 저장해 둔 명령을 실행합니다. 그 번호에 저장된 명령이 없으면 <strong>아무 일도 일어나지 않습니다.</strong></td></tr></tbody></table><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2>',25)),o(d,{id:"settings-after-action"}),r[1]||(r[1]=t("h2",{id:"사용-방법",tabindex:"-1"},[e("사용 방법 "),t("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),r[2]||(r[2]=t("p",null,[e("시점 하나에 동작을 지정하는 과정입니다. 예시는 "),t("strong",null,"After Servo On"),e("에 "),t("strong",null,"Run User Script 0"),e("을 지정합니다.")],-1)),o(n,{id:"settings-after-action"}),r[3]||(r[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"여러 시점 설정하기"),t("p",null,"시점마다 따로 저장합니다. 다른 시점을 고르면 선택 상자에 그 시점에 저장된 값이 나타납니다.")],-1)),r[4]||(r[4]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"저장에 실패하면"),t("p",null,'저장하지 못하면 "Set After Action Error" 창이 표시되고 카드의 값은 바뀌지 않습니다.')],-1))])}const v=s(f,[["render",b]]);export{S as __pageData,v as default};
